1.2 Live panel: the illuminated I–V characteristic (slide 10)


Show the Python
import {kT} from "./det_sim.js"
viewof pn = Inputs.form({
  P: Inputs.range([0, 100], {value: 20, step: 0.5, label: "optical power P_o (µW)"}),
  R: Inputs.range([0.05, 1.2], {value: 0.5, step: 0.01, label: "responsivity R (A/W)"}),
  lIo: Inputs.range([-14, -6], {value: -10, step: 0.1, label: "log₁₀ dark saturation current I_o (A)"}),
  eta: Inputs.range([1, 2], {value: 1, step: 0.05, label: "ideality factor η"}),
  Vr: Inputs.range([0, 10], {value: 5, step: 0.1, label: "reverse bias V_r (V)"})
})


















Show the Python
pnOut = {
  const Io = 10 ** pn.lIo, Iph = pn.R * pn.P * 1e-6, Vt = pn.eta * kT(300), dark = [], light = [];
  const Vmax = Math.max(0.15, Vt * Math.log(1 + 2 * Math.max(Iph, 1e-6) / Io));
  for (let i = 0; i &lt;= 600; i++) {
    const V = -Math.max(pn.Vr, 1) - 0.5 + (Vmax + Math.max(pn.Vr, 1) + 0.5) * i / 600;
    dark.push({V, I: 1e6 * Io * Math.expm1(V / Vt), c: "dark"});
    light.push({V, I: 1e6 * (Io * Math.expm1(V / Vt) - Iph), c: "illuminated"});
  }
  const Voc = Vt * Math.log1p(Iph / Io);
  return {pts: dark.concat(light), Iph, Io, Voc, Ir: Io * Math.expm1(-pn.Vr / Vt) - Iph, Vmax};
}
Plot.plot({
  width: Math.min(width, 1050), height: 320, x: {label: "diode voltage V (V)"}, y: {label: "current I (µA)", grid: true,
    domain: [-1.3 * Math.max(pnOut.Iph * 1e6, 1), 0.8 * Math.max(pnOut.Iph * 1e6, 1)]},
  color: {legend: true, domain: ["dark", "illuminated"], range: ["#52514e", "#e34948"]},
  marks: [Plot.ruleX([0]), Plot.ruleY([0]),
          Plot.line(pnOut.pts, {x: "V", y: "I", stroke: "c", strokeWidth: 2, clip: true}),
          Plot.dot([{V: -pn.Vr, I: 1e6 * pnOut.Ir}], {x: "V", y: "I", r: 6, fill: "#2a78d6", tip: true, title: () =&gt; "reverse-biased operating point"}),
          Plot.dot([{V: pnOut.Voc, I: 0}], {x: "V", y: "I", r: 6, fill: "#1baf7a", title: () =&gt; "open circuit"}),
          Plot.dot([{V: 0, I: -1e6 * pnOut.Iph}], {x: "V", y: "I", r: 6, fill: "#eda100", title: () =&gt; "short circuit"})]
})


















Show the Python
html`&lt;div class="result-box"&gt;
photocurrent I&lt;sub&gt;ph&lt;/sub&gt; = R P&lt;sub&gt;o&lt;/sub&gt; = &lt;b&gt;${(pnOut.Iph * 1e6).toFixed(3)} µA&lt;/b&gt; · dark current at −V&lt;sub&gt;r&lt;/sub&gt;: ${(pnOut.Io * 1e9).toPrecision(3)} nA
(${pnOut.Iph &gt; 0 ? (100 * pnOut.Io / pnOut.Iph).toPrecision(2) : "∞"} % of the signal)&lt;br&gt;
&lt;span style="color:#2a78d6"&gt;●&lt;/span&gt; reverse bias: I = ${(pnOut.Ir * 1e6).toFixed(3)} µA ·
&lt;span style="color:#eda100"&gt;●&lt;/span&gt; short circuit: I&lt;sub&gt;sc&lt;/sub&gt; = −I&lt;sub&gt;ph&lt;/sub&gt; ·
&lt;span style="color:#1baf7a"&gt;●&lt;/span&gt; open circuit: V&lt;sub&gt;oc&lt;/sub&gt; = &lt;b&gt;${(pnOut.Voc * 1e3).toFixed(1)} mV&lt;/b&gt;
&lt;/div&gt;`







Move the power slider: the reverse current and \(I_{sc}\) follow \(P_o\) linearly, while \(V_{oc}\) grows only by \(\eta k_BT\ln 10\) (60 mV for \(\eta=1\)) per decade of power. Raise \(I_o\) (a larger or hotter diode, a smaller band gap) and watch \(V_{oc}\) fall. This is why germanium and InGaAs photodiodes, with dark currents in the µA range (slide 49), make poor photovoltaic detectors and why InAs and InSb must be cooled.


Show the Python
Io, R = 1e-10, 0.5
V = np.linspace(-2, 0.6, 800)
fig, ax = plt.subplots(1, 2, figsize=(11, 3.8))
for P in (0, 5e-6, 10e-6, 20e-6):
    ax[0].plot(V, 1e6*dl.diode_current(V, Io, R*P), label=f"P_o = {P*1e6:.0f} µW")
ax[0].set(xlabel="V (V)", ylabel="I (µA)", ylim=(-12, 6)); ax[0].axhline(0, color=dl.INK2, lw=0.8); ax[0].axvline(0, color=dl.INK2, lw=0.8)
ax[0].legend(fontsize=8)
P = np.logspace(-12, -2, 200)
ax[1].loglog(P, R*P + Io, label="|I| at V_r = 5 V (A)")
ax2 = ax[1].twinx(); ax2.semilogx(P, dl.kT()*np.log1p(R*P/Io), color=dl.PALETTE[1], label="V_oc (V)")
ax2.set_ylabel("V_oc (V)", color=dl.PALETTE[1]); ax2.grid(False)
ax[1].set(xlabel="optical power P_o (W)", ylabel="reverse current (A)"); ax[1].legend(loc="upper left", fontsize=8)
plt.tight_layout(); plt.show()








Figure 1.1: Left: I–V curves of a photodiode (I_o = 0.1 nA, R = 0.5 A/W) for increasing optical power; the curves are the dark characteristic shifted down by I_ph = RP_o (slide 10). Right: in reverse bias the current is proportional to P_o over many decades, while V_oc grows logarithmically and saturates near the band-gap voltage.

2.2 Live panel: one electron–hole pair (slides 13–15)


Show the Python
import {driftVelocity, pinImpulse, transitMag, f3dB, alpha, qe} from "./det_sim.js"
viewof rm = Inputs.form({
  L: Inputs.range([1, 50], {value: 10, step: 0.5, label: "electrode spacing L (µm)"}),
  l: Inputs.range([0, 1], {value: 0.3, step: 0.01, label: "generation point l/L"}),
  V: Inputs.range([0.5, 100], {value: 10, step: 0.5, label: "applied voltage V (V)"}),
  sat: Inputs.toggle({label: "use Si drift velocities v(E) (else v_e = 2v_h = 10⁵ m/s)", value: true})
})


















Show the Python
rmOut = {
  const L = rm.L * 1e-6, E = rm.V / L;
  const ve = rm.sat ? driftVelocity(E, "e") : 1e5, vh = rm.sat ? driftVelocity(E, "h") : 5e4;
  const te = (1 - rm.l) * L / ve, th = rm.l * L / vh, tmax = 1.25 * Math.max(te, th, 1e-15), pts = [];
  for (let i = 0; i &lt;= 600; i++) {
    const t = tmax * i / 600, ie = t &lt; te ? qe * ve / L : 0, ih = t &lt; th ? qe * vh / L : 0;
    pts.push({t: t * 1e12, i: ie * 1e9, c: "electron i_e"}, {t: t * 1e12, i: ih * 1e9, c: "hole i_h"}, {t: t * 1e12, i: (ie + ih) * 1e9, c: "total"});
  }
  return {pts, E, ve, vh, te, th, Qe: (1 - rm.l), Qh: rm.l};
}
Plot.plot({
  width: Math.min(width, 1050), height: 280, x: {label: "time (ps)"}, y: {label: "induced current (nA)", grid: true},
  color: {legend: true, domain: ["electron i_e", "hole i_h", "total"], range: ["#2a78d6", "#e34948", "#0b0b0b"]},
  marks: [Plot.line(rmOut.pts, {x: "t", y: "i", stroke: "c", strokeWidth: 2, curve: "step-after"})]
})


















Show the Python
html`&lt;div class="result-box"&gt;E = ${(rmOut.E / 1e5).toFixed(2)} kV/cm · v&lt;sub&gt;e&lt;/sub&gt; = ${(rmOut.ve / 1e3).toFixed(1)} km/s, v&lt;sub&gt;h&lt;/sub&gt; = ${(rmOut.vh / 1e3).toFixed(1)} km/s&lt;br&gt;
t&lt;sub&gt;e&lt;/sub&gt; = ${(rmOut.te * 1e12).toFixed(1)} ps · t&lt;sub&gt;h&lt;/sub&gt; = ${(rmOut.th * 1e12).toFixed(1)} ps ·
charge carried by the electron ${rmOut.Qe.toFixed(2)} e, by the hole ${rmOut.Qh.toFixed(2)} e, total &lt;b&gt;1.00 e&lt;/b&gt;&lt;/div&gt;`







Set \(l/L\to 0\): the pair is created next to the electrode the hole drifts to. The hole contributes almost nothing; the electron crosses the whole device and carries the full charge. Raise the voltage with the Si velocities on: the current pulse grows taller and shorter until the carriers reach their saturation velocity (about \(10^5\) m/s, slide 31). Beyond that, more volts no longer buy speed.

2.3 Many pairs: the transit-time impulse response
A short light pulse creates pairs with the profile \(e^{-\alpha x}\) of Chapter 3 (light entering at \(x=0\), on the side where the holes are collected). The photocurrent is the sum of the rectangular pulses of all pairs. Its Fourier transform is the transit-time frequency response.


Show the Python
viewof tr = Inputs.form({
  W: Inputs.range([0.5, 50], {value: 10, step: 0.5, label: "drift-region width W (µm)"}),
  la: Inputs.range([3, 8], {value: 5, step: 0.05, label: "log₁₀ absorption coefficient α (m⁻¹)"}),
  ve: Inputs.range([1e4, 2e5], {value: 1e5, step: 1e3, label: "electron velocity v_e (m/s)"}),
  vh: Inputs.range([1e4, 2e5], {value: 7e4, step: 1e3, label: "hole velocity v_h (m/s)"})
})









Show the Python
trOut = {
  const W = tr.W * 1e-6, a = 10 ** tr.la, tmax = 1.1 * W / Math.min(tr.ve, tr.vh), ts = d3.range(0, 501).map(i =&gt; tmax * i / 500);
  const r = pinImpulse(ts, W, a, tr.ve, tr.vh, 300);
  const pts = r.flatMap(d =&gt; [{t: d.t * 1e12, i: d.ie / qe * 1e-12, c: "electrons"}, {t: d.t * 1e12, i: d.ih / qe * 1e-12, c: "holes"},
                               {t: d.t * 1e12, i: (d.ie + d.ih) / qe * 1e-12, c: "total"}]);
  const fmax = 2 * Math.max(tr.ve, tr.vh) / W;
  const resp = d3.range(0, 301).map(i =&gt; { const f = fmax * i / 300; return {f: f / 1e9, H: 20 * Math.log10(Math.max(transitMag(f, W, a, tr.ve, tr.vh), 1e-6))}; });
  return {pts, resp, f3: f3dB(f =&gt; transitMag(f, W, a, tr.ve, tr.vh), fmax), absorbed: 1 - Math.exp(-a * W), aW: a * W};
}
Plot.plot({
  width: Math.min(width, 1050), height: 250, x: {label: "time after the light pulse (ps)"}, y: {label: "current per EHP (e/ps)", grid: true},
  color: {legend: true, domain: ["electrons", "holes", "total"], range: ["#2a78d6", "#e34948", "#0b0b0b"]},
  marks: [Plot.line(trOut.pts, {x: "t", y: "i", stroke: "c", strokeWidth: 2})]
})


















Show the Python
Plot.plot({
  width: Math.min(width, 1050), height: 220, x: {label: "modulation frequency (GHz)"}, y: {label: "|H_transit| (dB)", domain: [-15, 1], grid: true},
  marks: [Plot.line(trOut.resp, {x: "f", y: "H", stroke: "#2a78d6", strokeWidth: 2}), Plot.ruleY([-3], {stroke: "#52514e", strokeDasharray: "3,3"})]
})









Show the Python
html`&lt;div class="result-box"&gt;αW = ${trOut.aW.toPrecision(3)} → fraction absorbed in the drift region ${(100 * trOut.absorbed).toFixed(1)} % ·
transit-limited bandwidth f&lt;sub&gt;3dB&lt;/sub&gt; = &lt;b&gt;${(trOut.f3 / 1e9).toFixed(2)} GHz&lt;/b&gt; = ${(trOut.f3 * tr.W * 1e-6 / Math.min(tr.ve, tr.vh)).toFixed(2)} × v&lt;sub&gt;slow&lt;/sub&gt;/W&lt;/div&gt;`







Strong absorption (\(\alpha W\gg1\)) creates all pairs near \(x=0\): only electrons cross the device, and the pulse lasts \(W/v_e\). Weak absorption gives uniform generation: both carriers contribute, each pulse is a triangle. Because the holes are slower, it pays to generate the carriers on the side where the holes are collected. This is why fast photodiodes are lit through the p⁺ side, and why the “uni-travelling-carrier” photodiode (see Going further) lets only electrons travel.


Show the Python
f = np.linspace(0, 15e9, 1500)
W, ve, vh = 10e-6, 1e5, 7e4
fig, ax = plt.subplots(figsize=(7.5, 3.6))
for a, lab in ((1e7, "αW = 100 (surface, electrons cross)"), (0, "uniform generation")):
    H = dl.transit_response(f, W, a, ve, vh)
    ax.plot(f/1e9, 20*np.log10(abs(H)), label=f"{lab}: f₃dB = {dl.f3dB(f, H)/1e9:.2f} GHz")
H = dl.transit_response(f, W, 1e7, vh, ve)       # swap roles: the slow carrier crosses
ax.plot(f/1e9, 20*np.log10(abs(H)), "--", label=f"surface, holes cross: f₃dB = {dl.f3dB(f, H)/1e9:.2f} GHz")
ax.axhline(-3, color=dl.INK2, ls=":", lw=1); ax.set(xlabel="f (GHz)", ylabel="|H| (dB)", ylim=(-15, 1)); ax.legend(fontsize=8); plt.show()








Figure 2.1: Transit-time frequency response of a 10 µm drift region (v_e = 10⁵ m/s, v_h = 7×10⁴ m/s) for surface absorption, uniform absorption, and absorption on the wrong side (light entering where the electrons are collected, so the slow holes cross the whole device).





For a single carrier crossing the whole width in \(t_{tr}=W/v\) the pulse is a rectangle and \(|H|=|\mathrm{sinc}(ft_{tr})|\), whose −3 dB point is \(f_{3dB}=0.443/t_{tr}=0.443\,v/W\). Uniform generation shares the work between the two carriers and is faster for the same width.

3.2 Live panel: absorption spectra and penetration depth (slide 16)


Show the Python
import {alpha, MATERIALS} from "./det_sim.js"
viewof ab = Inputs.form({
  mats: Inputs.checkbox(Object.keys(MATERIALS), {value: ["Si", "Ge", "GaAs", "In0.53Ga0.47As"], label: "materials"}),
  wl: Inputs.range([300, 1850], {value: 850, step: 5, label: "wavelength λ (nm)"}),
  d: Inputs.range([0.1, 100], {value: 5, step: 0.1, label: "layer thickness d (µm)"})
})


















Show the Python
abOut = {
  const pts = [];
  for (const m of ab.mats) for (let i = 0; i &lt;= 400; i++) { const wl = 0.3 + 1.6 * i / 400, a = alpha(m, wl * 1e-6); if (a &gt; 0) pts.push({wl, a, m}); }
  const rows = ab.mats.map(m =&gt; { const a = alpha(m, ab.wl * 1e-9); return {m, a, delta: a &gt; 0 ? 1e6 / a : Infinity, abs: 1 - Math.exp(-a * ab.d * 1e-6)}; });
  return {pts, rows};
}
Plot.plot({
  width: Math.min(width, 1050), height: 330, x: {label: "wavelength (µm)", domain: [0.3, 1.9]},
  y: {label: "α (m⁻¹)", type: "log", domain: [1e3, 1e8], grid: true}, color: {legend: true},
  marks: [Plot.line(abOut.pts, {x: "wl", y: "a", stroke: "m", strokeWidth: 2}), Plot.ruleX([ab.wl / 1000], {stroke: "#52514e", strokeDasharray: "4,3"})]
})


















Show the Python
html`&lt;div class="result-box"&gt;at λ = ${ab.wl} nm (hν = ${(1239.84 / ab.wl).toFixed(3)} eV):&lt;br&gt;
${abOut.rows.map(r =&gt; html`&lt;b&gt;${r.m}&lt;/b&gt;: α = ${r.a &gt; 0 ? r.a.toExponential(2) + " m⁻¹" : "0 (λ &gt; λ&lt;sub&gt;g&lt;/sub&gt;)"},
δ = ${isFinite(r.delta) ? (r.delta &lt; 1 ? (r.delta * 1e3).toFixed(0) + " nm" : r.delta.toPrecision(3) + " µm") : "∞"},
absorbed in ${ab.d} µm: &lt;b&gt;${(100 * r.abs).toFixed(1)} %&lt;/b&gt;&lt;br&gt;`)}&lt;/div&gt;`







Things to try: at 850 nm (short-reach datacom), 3 µm of GaAs absorbs most of the light while Si needs about 50 µm. At 1310 and 1550 nm silicon is transparent; Ge and InGaAs absorb, and InGaAsP with \(E_g=0.89\) eV stops at 1.4 µm. At 400 nm everything absorbs within a few tens of nm: the surface (and its recombination) controls the blue response (Chapter 4).


Show the Python
wl = np.linspace(0.3e-6, 1.9e-6, 1000)
fig, ax = plt.subplots(figsize=(8, 4.4))
for m, c in zip(dl.MATERIALS, dl.PALETTE):
    a = dl.alpha(m, wl); ax.semilogy(wl[a &gt; 0]*1e6, a[a &gt; 0], color=c, label=m)
    ax.axvline(dl.cutoff_wavelength(dl.MATERIALS[m]["Eg"])*1e6, color=c, ls=":", lw=1)
ax.set(xlabel="wavelength (µm)", ylabel="α (m⁻¹)", ylim=(1e3, 1e8), xlim=(0.3, 1.9)); ax.legend(fontsize=8, ncol=2)
sec = ax.secondary_yaxis("right", functions=(lambda a: 1e6/np.maximum(a, 1e-30), lambda d: 1e6/np.maximum(d, 1e-30)))
sec.set_ylabel("penetration depth δ (µm)"); plt.show()








Figure 3.1: Absorption coefficient versus wavelength at 300 K (cf. slide 16). Right axis: penetration depth δ = 1/α. Si data from Green (2008); Ge, GaAs, InP and InGaAsP digitised from the slide figure; In₀.₅₃Ga₀.₄₇As from the literature. Dotted lines: cut-off wavelengths λ_g = 1.24/E_g.

3.4 Live panel: the absorption edge moves with temperature (slide 35)
The band gap shrinks as the lattice expands and phonons multiply (Varshni, \(E_g(T)=E_{g0}-aT^2/(T+b)\)). The absorption edge, and hence the long-wavelength cut-off of the responsivity, moves to longer wavelengths when the detector warms up. Slide 35 shows it for an InAs photodiode. The model below is a generic direct-gap edge, \(\alpha=A\sqrt{h\nu-E_g}\) joined to an exponential (Urbach) tail of width \(E_U\).


Show the Python
VARSHNI = ({"InAs (0.417, 2.76e-4, 93)": [0.417, 2.76e-4, 93, 3.6e6], "In0.53Ga0.47As (0.81, 4.9e-4, 301)": [0.81, 4.9e-4, 301, 3e6],
            "GaAs (1.519, 5.405e-4, 204)": [1.519, 5.405e-4, 204, 4e6], "InSb (0.24, 6e-4, 500)": [0.24, 6e-4, 500, 3e6]})
viewof vt = Inputs.form({
  mat: Inputs.select(Object.keys(VARSHNI), {label: "material (E_g0 eV, a eV/K, b K)"}),
  T1: Inputs.range([4, 400], {value: 233, step: 1, label: "temperature T₁ (K)"}),
  T2: Inputs.range([4, 400], {value: 295, step: 1, label: "temperature T₂ (K)"}),
  EU: Inputs.range([1, 30], {value: 7, step: 0.5, label: "Urbach energy E_U (meV)"}),
  d: Inputs.range([0.5, 20], {value: 3, step: 0.1, label: "absorber thickness (µm)"})
})


















Show the Python
vtOut = {
  const [Eg0, a, b, A] = VARSHNI[vt.mat], Eg = T =&gt; Eg0 - a * T * T / (T + b), EU = vt.EU / 1000;
  const alphaE = (E, g) =&gt; { const E1 = g + EU / 2; return E &gt; E1 ? A * Math.sqrt(E - g) : A * Math.sqrt(EU / 2) * Math.exp((E - E1) / EU); };
  const g1 = Eg(vt.T1), g2 = Eg(vt.T2), lg = 1.23984 / Math.min(g1, g2), pts = [];
  for (let i = 0; i &lt;= 500; i++) {
    const wl = 0.6 * lg + 0.6 * lg * i / 500, E = 1.23984 / wl;
    for (const [T, g] of [[vt.T1, g1], [vt.T2, g2]]) {
      const al = alphaE(E, g); pts.push({wl, eta: (1 - Math.exp(-al * vt.d * 1e-6)) , R: (1 - Math.exp(-al * vt.d * 1e-6)) * wl / 1.23984, T: `T = ${T} K`});
    }
  }
  return {pts, g1, g2};
}
Plot.plot({
  width: Math.min(width, 1050), height: 280, x: {label: "wavelength (µm)"}, y: {label: "responsivity for η_i = T = 1 (A/W)", grid: true},
  color: {legend: true}, marks: [Plot.line(vtOut.pts, {x: "wl", y: "R", stroke: "T", strokeWidth: 2})]
})


















Show the Python
html`&lt;div class="result-box"&gt;E&lt;sub&gt;g&lt;/sub&gt;(T₁) = ${vtOut.g1.toFixed(4)} eV → λ&lt;sub&gt;g&lt;/sub&gt; = ${(1.23984 / vtOut.g1).toFixed(3)} µm ·
E&lt;sub&gt;g&lt;/sub&gt;(T₂) = ${vtOut.g2.toFixed(4)} eV → λ&lt;sub&gt;g&lt;/sub&gt; = ${(1.23984 / vtOut.g2).toFixed(3)} µm ·
shift ${(1000 * (1.23984 / vtOut.g2 - 1.23984 / vtOut.g1)).toFixed(0)} nm (dE&lt;sub&gt;g&lt;/sub&gt;/dT ≈ ${(1e6 * (vtOut.g2 - vtOut.g1) / (vt.T2 - vt.T1)).toFixed(0)} µeV/K)&lt;/div&gt;`







Two lessons. First, the long-wavelength edge of a detector is not a sharp line: the Urbach tail and a thick absorber push it beyond \(\lambda_g\), which is how InGaAs photodiodes still respond at 1.65–1.7 µm. Second, a detector operated near its cut-off is a thermometer: at 1.65 µm the responsivity of InGaAs changes by several % per kelvin. Wavelength-critical measurements near the edge need temperature control.






TipGoing further






Indirect absorption has two branches. Phonon absorption gives \(\alpha_a\propto(h\nu-E_g+h\vartheta)^2/(e^{h\vartheta/k_BT}-1)\) and phonon emission \(\alpha_e\propto(h\nu-E_g-h\vartheta)^2/(1-e^{-h\vartheta/k_BT})\). Plot \(\sqrt\alpha\) versus \(h\nu\) for Si near 1.1 µm (“Macfarlane plot”) and extract \(E_g\) and the phonon energy (≈ 58 meV). Why does Si absorb less at 1.1 µm when it is cooled?
Free-carrier absorption (\(\alpha_{fc}\propto n\lambda^2\)) competes in heavily doped contact layers and limits the long-wavelength transparency of substrates (Ch. 4, the silicon laser problem).
Two-photon absorption lets a Si detector respond to intense 1.55 µm pulses (\(\alpha=\beta I\), \(\beta\approx1\) cm/GW): it is used for autocorrelators of femtosecond pulses. What intensity gives the same α as one-photon absorption at 1.1 µm?
Kramers–Kronig. Absorption and refractive index are linked (Ch. 1). The strong band-edge absorption of InGaAs causes the dispersion of \(n\) that sets the group index of laser cavities (Ch. 4).










NoteComplements






M. A. Green, “Self-consistent optical parameters of intrinsic silicon at 300 K”, Sol. Energy Mater. Sol. Cells 92, 1305 (2008).
I. Vurgaftman, J. R. Meyer, L. R. Ram-Mohan, “Band parameters for III–V compound semiconductors”, J. Appl. Phys. 89, 5815 (2001): Varshni parameters.
The refractive-index database https://refractiveindex.info gives tabulated \(n\) and \(k\) (\(\alpha=4\pi k/\lambda\)) for all these materials.

4.2 Live panel: responsivity from the device structure (slides 27, 139–145)


Show the Python
import {alpha, MATERIALS, responsivity, fresnelT, structureR, qeff} from "./det_sim.js"
viewof rs = Inputs.form({
  mat: Inputs.select(Object.keys(MATERIALS), {value: "Si", label: "absorbing material"}),
  lp: Inputs.range([0.01, 3], {value: 0.5, step: 0.01, label: "p⁺ layer ℓ_p (µm)"}),
  Le: Inputs.range([0, 3], {value: 0.1, step: 0.01, label: "electron diffusion length in p⁺, L_e (µm)"}),
