  const hist = d3.rollups(counts, g =&gt; g.length, d =&gt; d).map(([k, n]) =&gt; ({k, f: n / sn.bins}));
  const fac = (k) =&gt; { let s = 0; for (let i = 2; i &lt;= k; i++) s += Math.log(i); return s; };
